+    _spill.writer.reset();
+    ASSIGN_OR_RETURN(_spill.reader, FileSystem::Default()->new_random_access_file(_spill.path));
+    _spill.ready = true;
+    TRACE_COUNTER_INCREMENT("pcu_spill_bytes", _spill.size);
+    return Status::OK();
+}
